Here is the commit message:
bus: mhi: core: Fix null pointer access when parsing MHI
 configuration

Functions parse_ev_cfg() and parse_ch_cfg() access mhi_cntrl->mhi_dev
before it is set in function mhi_register_controller(),
use cntrl_dev instead of mhi_dev.

Fixes: 0cbf260820fa ("bus: mhi: core: Add support for registering MHI controllers")
Signed-off-by: Carl Yin <carl.yin@quectel.com>
Reviewed-by: Bhaumik Bhatt <bbhatt@codeaurora.org>
Reviewed-by: Hemant Kumar <hemantk@codeaurora.org>
Reviewed-by: Manivannan Sadhasivam <manivannan.sadhasivam@linaro.org>
Signed-off-by: Manivannan Sadhasivam <manivannan.sadhasivam@linaro.org>

Here is the root cause:
The bug was caused by the functions `parse_ev_cfg()` and `parse_ch_cfg()` attempting to access the `mhi_dev` member of the `mhi_controller` structure before it was properly initialized in the `mhi_register_controller()` function. This resulted in a null pointer dereference when the code tried to access `mhi_cntrl->mhi_dev->dev`, leading to potential crashes or undefined behavior.

Here is the patch:

 static int parse_ev_cfg(struct mhi_controller *mhi_cntrl,
 			const struct mhi_controller_config *config)
 {
 	struct mhi_event *mhi_event;
 	const struct mhi_event_config *event_cfg;
-	struct device *dev = &mhi_cntrl->mhi_dev->dev;
+	struct device *dev = mhi_cntrl->cntrl_dev;
 	int i, num;

 	num = config->num_events;
 	mhi_cntrl->total_ev_rings = num;
 	mhi_cntrl->mhi_event = kcalloc(num, sizeof(*mhi_cntrl->mhi_event),
 				       GFP_KERNEL);
 	if (!mhi_cntrl->mhi_event)
 		return -ENOMEM;

 	/* Populate event ring */
 	mhi_event = mhi_cntrl->mhi_event;
 	for (i = 0; i < num; i++) {
 		event_cfg = &config->event_cfg[i];

 		mhi_event->er_index = i;
 		mhi_event->ring.elements = event_cfg->num_elements;
 		mhi_event->intmod = event_cfg->irq_moderation_ms;
 		mhi_event->irq = event_cfg->irq;

 		if (event_cfg->channel != U32_MAX) {
 			/* This event ring has a dedicated channel */
 			mhi_event->chan = event_cfg->channel;
 			if (mhi_event->chan >= mhi_cntrl->max_chan) {
 				dev_err(dev,
 					"Event Ring channel not available\n");
 				goto error_ev_cfg;
 			}

 			mhi_event->mhi_chan =
 				&mhi_cntrl->mhi_chan[mhi_event->chan];
 		}

 		/* Priority is fixed to 1 for now */
 		mhi_event->priority = 1;

 		mhi_event->db_cfg.brstmode = event_cfg->mode;
 		if (MHI_INVALID_BRSTMODE(mhi_event->db_cfg.brstmode))
 			goto error_ev_cfg;

 		if (mhi_event->db_cfg.brstmode == MHI_DB_BRST_ENABLE)
 			mhi_event->db_cfg.process_db = mhi_db_brstmode;
 		else
 			mhi_event->db_cfg.process_db = mhi_db_brstmode_disable;

 		mhi_event->data_type = event_cfg->data_type;

 		switch (mhi_event->data_type) {
 		case MHI_ER_DATA:
 			mhi_event->process_event = mhi_process_data_event_ring;
 			break;
 		case MHI_ER_CTRL:
 			mhi_event->process_event = mhi_process_ctrl_ev_ring;
 			break;
 		default:
 			dev_err(dev, "Event Ring type not supported\n");
 			goto error_ev_cfg;
 		}

 		mhi_event->hw_ring = event_cfg->hardware_event;
 		if (mhi_event->hw_ring)
 			mhi_cntrl->hw_ev_rings++;
 		else
 			mhi_cntrl->sw_ev_rings++;

 		mhi_event->cl_manage = event_cfg->client_managed;
 		mhi_event->offload_ev = event_cfg->offload_channel;
 		mhi_event++;
 	}

 	return 0;

 error_ev_cfg:

 	kfree(mhi_cntrl->mhi_event);
 	return -EINVAL;
 }

 static int parse_ch_cfg(struct mhi_controller *mhi_cntrl,
 			const struct mhi_controller_config *config)
 {
 	const struct mhi_channel_config *ch_cfg;
-	struct device *dev = &mhi_cntrl->mhi_dev->dev;
+	struct device *dev = mhi_cntrl->cntrl_dev;
 	int i;
 	u32 chan;

 	mhi_cntrl->max_chan = config->max_channels;

 	/*
 	 * The allocation of MHI channels can exceed 32KB in some scenarios,
 	 * so to avoid any memory possible allocation failures, vzalloc is
 	 * used here
 	 */
 	mhi_cntrl->mhi_chan = vzalloc(mhi_cntrl->max_chan *
 				      sizeof(*mhi_cntrl->mhi_chan));
 	if (!mhi_cntrl->mhi_chan)
 		return -ENOMEM;

 	INIT_LIST_HEAD(&mhi_cntrl->lpm_chans);

 	/* Populate channel configurations */
 	for (i = 0; i < config->num_channels; i++) {
 		struct mhi_chan *mhi_chan;

 		ch_cfg = &config->ch_cfg[i];

 		chan = ch_cfg->num;
 		if (chan >= mhi_cntrl->max_chan) {
 			dev_err(dev, "Channel %d not available\n", chan);
 			goto error_chan_cfg;
 		}

 		mhi_chan = &mhi_cntrl->mhi_chan[chan];
 		mhi_chan->name = ch_cfg->name;
 		mhi_chan->chan = chan;

 		mhi_chan->tre_ring.elements = ch_cfg->num_elements;
 		if (!mhi_chan->tre_ring.elements)
 			goto error_chan_cfg;

 		/*
 		 * For some channels, local ring length should be bigger than
 		 * the transfer ring length due to internal logical channels
 		 * in device. So host can queue much more buffers than transfer
 		 * ring length. Example, RSC channels should have a larger local
 		 * channel length than transfer ring length.
 		 */
 		mhi_chan->buf_ring.elements = ch_cfg->local_elements;
 		if (!mhi_chan->buf_ring.elements)
 			mhi_chan->buf_ring.elements = mhi_chan->tre_ring.elements;
 		mhi_chan->er_index = ch_cfg->event_ring;
 		mhi_chan->dir = ch_cfg->dir;

 		/*
 		 * For most channels, chtype is identical to channel directions.
 		 * So, if it is not defined then assign channel direction to
 		 * chtype
 		 */
 		mhi_chan->type = ch_cfg->type;
 		if (!mhi_chan->type)
 			mhi_chan->type = (enum mhi_ch_type)mhi_chan->dir;

 		mhi_chan->ee_mask = ch_cfg->ee_mask;
 		mhi_chan->db_cfg.pollcfg = ch_cfg->pollcfg;
 		mhi_chan->lpm_notify = ch_cfg->lpm_notify;
 		mhi_chan->offload_ch = ch_cfg->offload_channel;
 		mhi_chan->db_cfg.reset_req = ch_cfg->doorbell_mode_switch;
 		mhi_chan->pre_alloc = ch_cfg->auto_queue;
 		mhi_chan->auto_start = ch_cfg->auto_start;

 		/*
 		 * If MHI host allocates buffers, then the channel direction
 		 * should be DMA_FROM_DEVICE
 		 */
 		if (mhi_chan->pre_alloc && mhi_chan->dir != DMA_FROM_DEVICE) {
 			dev_err(dev, "Invalid channel configuration\n");
 			goto error_chan_cfg;
 		}

 		/*
 		 * Bi-directional and direction less channel must be an
 		 * offload channel
 		 */
 		if ((mhi_chan->dir == DMA_BIDIRECTIONAL ||
 		     mhi_chan->dir == DMA_NONE) && !mhi_chan->offload_ch) {
 			dev_err(dev, "Invalid channel configuration\n");
 			goto error_chan_cfg;
 		}

 		if (!mhi_chan->offload_ch) {
 			mhi_chan->db_cfg.brstmode = ch_cfg->doorbell;
 			if (MHI_INVALID_BRSTMODE(mhi_chan->db_cfg.brstmode)) {
 				dev_err(dev, "Invalid Door bell mode\n");
 				goto error_chan_cfg;
 			}
 		}

 		if (mhi_chan->db_cfg.brstmode == MHI_DB_BRST_ENABLE)
 			mhi_chan->db_cfg.process_db = mhi_db_brstmode;
 		else
 			mhi_chan->db_cfg.process_db = mhi_db_brstmode_disable;

 		mhi_chan->configured = true;

 		if (mhi_chan->lpm_notify)
 			list_add_tail(&mhi_chan->node, &mhi_cntrl->lpm_chans);
 	}

 	return 0;

 error_chan_cfg:
 	vfree(mhi_cntrl->mhi_chan);

 	return -EINVAL;
 }



